-- พื้นที่ · ทีม (+ชื่อจากทะเบียน HR 16-11-69 · หน่วยงานย่อยตามกติกาเดิม) · หัวข้อตรวจ · แผนตรวจ — รหัสแถว (uuid) เดิม
-- ต้องลง 20261127_act02_5s_main.sql ก่อน · รันซ้ำได้ (on conflict อัปเดตค่าล่าสุด)
-- ตรวจ: select (select count(*) from act02_area) area, (select count(*) from act02_team) team, (select count(*) from act02_checklist) checklist, (select count(*) from act02_audit_plan) plan;
-- ย้อนกลับ: delete from act02_audit_plan; delete from act02_team; delete from act02_checklist; delete from act02_area;

on conflict (act_area) do update set area_code = excluded.area_code, area_type = excluded.area_type, act_area_name = excluded.act_area_name, section = excluded.section, status = excluded.status;

on conflict (act_checklist) do update set year = excluded.year, item_no = excluded.item_no, s_group = excluded.s_group, act_checklist_name = excluded.act_checklist_name, score_max = excluded.score_max, status = excluded.status;

on conflict (act_team) do update set employee_name = coalesce(excluded.employee_name, public.act02_team.employee_name), role = excluded.role, team = excluded.team, act_area = excluded.act_area, unit = excluded.unit, status = excluded.status, team_key = excluded.team_key;

on conflict (act_audit_plan) do update set year = excluded.year, act_area = excluded.act_area, month = excluded.month, week = excluded.week, round = excluded.round, team = excluded.team;

